Notation FB0 F := (mkABlock (ABFake 0) F 64).

(* [comment removed for export] *)
Definition x2_frame (L : alayout) (RNG : footprint) (st : astate) (LB : list ablock) (m m3 : amem)
    (ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (SPV lo FF : Z) : Prop :=
  FF mod 64 = 0 /\ ablk FF (FF + 64) /\ FF + 64 <= ATOP /\ rng RNG FF 64 /\ rng RNG (shad FF) 8
  /\ (forall b, In b LB -> FF + 64 <= ab_addr b \/ ab_addr b + ab_size b <= FF)
  /\ AHEAP AI L RNG st (FB0 FF :: LB) m3
  /\ magree asegs (aclient_addr CI LB SPV) m m3 /\ mem_inv asegs m3
  /\ rw_cells asegs m3 (SPV + -104) (FRBx2 ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11)
  /\ rw_cells asegs m3 (shad FF) FDSH
  /\ stk asegs m3 lo (SPAx2 SPV) /\ stk asegs m3 (SPAx2 SPV + 728) (SPV + -104).

