    (SPV DT W S size flags lo mtl : Z) (pdt : aptr) (Q : machine_state -> Prop),
  AHEAP AI L RNG st LB m -> (forall F k, ~ In (mkABlock (ABFake 0) F k) LB) ->
  (forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b)) ->
  stk asegs m lo SPV -> ATOP + 4096 <= lo -> lo <= SPV - HUF_RDT_STACK_A2 ->
  SPV + 16 < al_top L -> SPV mod 16 = 0 ->
  mem_inv asegs m -> tp = Z_to_bv 64 ATP ->
  rng RNG lo (al_top L - lo) -> rng_aimg RNG -> rng_fs L RNG ->
  1 <= mtl <= 12 -> In (HB pdt DT (DTABLE_BYTES mtl)) LB -> rw_cells asegs m DT [C4 (Z_to_bv 64 (mtl * 16777217))] ->
  (forall (FF : Z) (m3 : amem) (j56 j72 j104 j144 j24 : list byte) (y5 y6 y7 y15 y16 y28 y29 y30 y31 : word),
     x2_frame L RNG st LB m m3 ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 SPV lo FF ->
     rw_cells asegs m3 (SPAx2 SPV) [CB 56 j56; C8 (Z_to_bv 64 (Z.shiftr DT 3 + 2147450880)); C8 (Z_to_bv 64 (mtl * 16777217));
                                   CB 24 j72; C8 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)); CB 8 j104; C8 (Z_to_bv 64 FF);
                                   C8 (Z_to_bv 64 FF); C8 (Z_to_bv 64 DT); C8 (Z_to_bv 64 W); CB 576 j144; C8 (Z_to_bv 64 FF)] ->
     rw_cells asegs m3 FF (X2HDR FF (fflag L 0 FF) j24) ->
     rw_cells asegs m3 DT [C4 (Z_to_bv 64 (mtl * 16777217))] ->
     evtF asegs RNG Q
       (MS (mkR (Z_to_bv 64 0x81674) (Z_to_bv 64 (SPAx2 SPV)) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 (SPAx2 SPV))
                (Z_to_bv 64 (W + 624)) (Z_to_bv 64 0) (Z_to_bv 64 112) (Z_to_bv 64 W)
                (Z_to_bv 64 (Z.shiftr DT 3 + 2147450880)) y15 y16 (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880))
                (Z_to_bv 64 S) (Z_to_bv 64 FF) s4 (Z_to_bv 64 W) (Z_to_bv 64 mtl) (Z_to_bv 64 size) (Z_to_bv 64 2147450880)
                (Z_to_bv 64 flags) s10 (Z_to_bv 64 (W + 624)) y28 y29 y30 y31)
           FR (Z_to_bv 64 0x515b0) fc None m3 (seg_rom asegs))) ->
  evtF asegs RNG Q
    (MS (mkR ra (Z_to_bv 64 SPV) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 DT) (Z_to_bv 64 S) (Z_to_bv 64 size) (Z_to_bv 64 W)
             (Z_to_bv 64 8704) (Z_to_bv 64 flags) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        FR (Z_to_bv 64 0x814ec) fc None m (seg_rom asegs)).
