Lemma x2_close : forall (L : alayout) (RNG : footprint)
    (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32)
    (m m4 : amem) (st : astate) (LB : list ablock) (SPV DT W mtl lo FF rv : Z) (pdt pw : aptr)
